/// Detect conflicts between I002 (missing-required-import) and PYI025
/// (unaliased-collections-abc-set-import).
///
/// PYI025 requires `from collections.abc import Set` to be aliased as `AbstractSet`, so a
/// required import of an unaliased `collections.abc.Set` is fundamentally incompatible with the
/// rule being enabled.
fn conflicting_required_import_pyi025(
    isort: &isort::settings::Settings,
    rules: &RuleTable,
) -> Result<()> {
    if !rules.enabled(Rule::UnaliasedCollectionsAbcSetImport) {
        return Ok(());
    }

    for required_import in &isort.required_imports {
        if required_import.qualified_name().to_string() == "collections.abc.Set"
            && required_import.bound_name() != "AbstractSet"
        {
            return Err(anyhow!(
                "Required import `from collections.abc import Set` specified in \
                `lint.isort.required-imports` (I002) conflicts with \
                `unaliased-collections-abc-set-import` (PYI025), which requires this import to \
                be aliased as `AbstractSet`.\n\
                Either alias the required import \
                (`from collections.abc import Set as AbstractSet`), or disable PYI025."
            ));
        }
    }

    Ok(())
}

